import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

public class IteratorDemo {
    public static void main(String[] args) {
        // Fail-fast demonstration
        List<String> failFastList = new ArrayList<>();
        failFastList.add("A");
        failFastList.add(
            "B"
        );

        try {
            Iterator<String> fastIt = failFastList.iterator();
            while (fastIt.hasNext()) {
                String item = fastIt.next();
                if (item.equals("A")) {
                    failFastList.add("C"); // Triggers ConcurrentModificationException
                }
            }
        } catch (java.util.ConcurrentModificationException e) {
            System.out.println("Caught expected Fail-fast exception: " + e);
        }

        // Fail-safe demonstration
        List<String> failSafeList = new CopyOnWriteArrayList<>();
        failSafeList.add("X");
        failSafeList.add("Y");

        Iterator<String> safeIt = failSafeList.iterator();
        while (safeIt.hasNext()) {
            String item = safeIt.next();
            if (item.equals("X")) {
                failSafeList.add("Z"); // Allowed; operates on snapshot
            }
        }
        System.out.println("Fail-safe list after modification: " + failSafeList);
    }
}
